 private void registerRealtimeReceiver(){if(messageReceiver!=null)return;messageReceiver=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(!"com.wethaq.MESSAGE_RECEIVED".equals(intent.getAction()))return;String senderId=intent.getStringExtra("sender_wethaq_id");if(activeId!=null&&activeId.equals(senderId))loadMessages();}};IntentFilter f=new IntentFilter("com.wethaq.MESSAGE_RECEIVED");if(Build.VERSION.SDK_INT>=33)registerReceiver(messageReceiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(messageReceiver,f);}
