 private void login(){base("مدير ومؤسس وثاق حاتم حسين الحاج رمضان");ImageView visual=new ImageView(this);visual.setImageResource(R.drawable.wethaq_identity);visual.setScaleType(ImageView.ScaleType.CENTER_INSIDE);content.addView(visual,lp(-1,150,8));TextView x=tv("هوية رقمية آمنة",25,Color.WHITE);x.setGravity(Gravity.CENTER);content.addView(x,lp(-1,-2,18));EditText n=field("الاسم الثلاثي (ثابت بعد إنشاء الهوية)"),y=field("سنة الميلاد (ثابت بعد إنشاء الهوية)"),code=field("رمز المرور الشخصي (6-12 أرقام)");y.setInputType(InputType.TYPE_CLASS_NUMBER);code.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);content.addView(n,lp(-1,64,10));content.addView(y,lp(-1,64,10));content.addView(code,lp(-1,64,14));Button l=btn("تسجيل الدخول"),c=btn("إنشاء هوية جديدة");content.addView(l,lp(-1,76,10));content.addView(c,lp(-1,76,14));l.bringToFront();c.bringToFront();l.setEnabled(true);c.setEnabled(true);content.addView(tv("المؤسس: حاتم حسين الحاج رمضان",14,gold()));l.setOnClickListener(v->{click();auth(n.getText().toString().trim(),y.getText().toString().trim(),code.getText().toString().trim(),false);});c.setOnClickListener(v->{click();auth(n.getText().toString().trim(),y.getText().toString().trim(),code.getText().toString().trim(),true);});}
 private void auth(String n,String y,String code,boolean create){final String name=n.trim(),year=y.trim();if(name.split("\\s+").length<3||!year.matches("\\d{4}")||!code.matches("\\d{6,12}")){toast("أدخل الاسم الثلاثي وسنة الميلاد ورمز المرور الشخصي (6-12 أرقام)");return;}io.execute(()->{try{JSONObject q=new JSONObject();q.put("name",name);q.put("birthYear",Integer.parseInt(year));q.put("personalCode",code);q.put("deviceKey",deviceKey());HttpResult r=request("POST",create?"/api/identity":"/api/login",q.toString(),null);if(r.code>=200&&r.code<300){JSONObject o=new JSONObject(r.body),u=o.getJSONObject("user");prefs.edit().putString(T,o.getString("token")).putString(ID,u.optString("wethaq_id")).putString("db_user_id",u.optString("id")).putString(NAME,u.optString("name",name)).putString(YEAR,year).apply();h.post(this::home);}else{final HttpResult result=r;h.post(()->toast(error(result)));}}catch(Exception e){h.post(()->toast("تعذر الاتصال بالخادم"));}});}
 private void openNotificationConversation(Intent intent){if(intent==null)return;String target=intent.getStringExtra("notification_target");if(target==null||target.trim().isEmpty())return;String name=intent.getStringExtra("notification_name");h.postDelayed(()->conversation(target.trim(),name==null||name.isEmpty()?target:name),120);} @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(hasToken()){home();openNotificationConversation(intent);}} 
 private void startMessageService(){try{Intent i=new Intent(this,WethaqMessageService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}}
 private void home(){stopPolling();base("المؤسس: حاتم حسين الحاج رمضان");TextView me=tv(prefs.getString(NAME,"")+"\n"+prefs.getString(ID,""),18,Color.WHITE);me.setGravity(Gravity.CENTER);content.addView(me,lp(-1,-2,12));ImageView visual=new ImageView(this);visual.setImageResource(R.drawable.wethaq_identity);visual.setScaleType(ImageView.ScaleType.CENTER_INSIDE);content.addView(visual,lp(-1,150,8));menu("⌕  البحث",this::searchScreen);menu("◉  جهات الاتصال",this::contactsScreen);menu("⚙  الإعدادات",this::settingsScreen);menu("♙  المعلومات الشخصية",this::profileScreen);menu("⚠  الشكاوى والتواصل مع المؤسس",this::sendComplaint);menu("👥  الإدارة",()->startActivity(new Intent(this,PublicAdministrationActivity.class)));if(isOwner())menu("🛡  لوحة تحكم المؤسس",this::adminScreen);Button out=btn("تسجيل الخروج");content.addView(out,lp(-1,76,8));out.setOnClickListener(v->{click();stopService(new Intent(this,WethaqMessageService.class));prefs.edit().remove(T).remove(ID).remove("db_user_id").remove(NAME).remove(YEAR).apply();activeId=null;activeName=null;login();});if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestNotifications();startMessageService();}
