 private void searchScreen(){base("البحث عن مستخدم");EditText q=field("الاسم أو معرف وَثاق");Button go=btn("بحث"),back=btn("رجوع");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(q,lp(-1,64,8));content.addView(go,lp(-1,76,8));content.addView(list);content.addView(back,lp(-1,76,8));go.setOnClickListener(v->{click();search(q.getText().toString().trim(),list);});back.setOnClickListener(v->{click();home();});}
 private void search(String q,LinearLayout list){if(q.length()<2){toast("أدخل حرفين على الأقل");return;}io.execute(()->{try{HttpResult r=request("GET","/api/search?q="+URLEncoder.encode(q,"UTF-8"),null,null);if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("users");h.post(()->{list.removeAllViews();if(a==null||a.length()==0){list.addView(tv("لا توجد نتائج",16,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);String id=u.optString("wethaq_id"),n=u.optString("name");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);ImageView avatar=new ImageView(this);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setImageDrawable(defaultAvatar());row.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout text=new LinearLayout(this);text.setOrientation(LinearLayout.VERTICAL);TextView nm=tv(n,18,Color.WHITE),wi=tv(id,13,Color.LTGRAY);text.addView(nm);text.addView(wi);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));Button save=btn("حفظ");row.addView(save,new LinearLayout.LayoutParams(dp(92),dp(68)));list.addView(row,lp(-1,-2,10));loadAvatarInto(id,avatar);save.setOnClickListener(v->{click();saveContact(id,n);});row.setOnClickListener(v->{click();saveContact(id,n);conversation(id,n);});}});}else{final HttpResult result=r;h.post(()->toast(error(result)));}}catch(Exception e){h.post(()->toast("فشل البحث"));}});}
 private Drawable defaultAvatar(){GradientDrawable d=new GradientDrawable();d.setShape(GradientDrawable.OVAL);d.setColor(Color.rgb(48,48,54));d.setStroke(dp(2),gold());d.setSize(dp(50),dp(50));return d;}
 private void saveContact(String id,String n){if(id==null||id.trim().isEmpty())return;io.execute(()->{try{JSONObject q=new JSONObject();q.put("wethaqId",id.trim());HttpResult r=request("POST","/api/contacts",q.toString(),auth());if(r.code==201||r.code==200){try{JSONArray a=contacts();boolean exists=false;for(int i=0;i<a.length();i++)if(id.equals(a.optJSONObject(i).optString("wethaq_id"))){exists=true;break;}if(!exists){JSONObject o=new JSONObject();o.put("wethaq_id",id);o.put("name",n==null||n.trim().isEmpty()?"مستخدم":n.trim());a.put(o);prefs.edit().putString(contactsStorageKey(),a.toString()).apply();}}catch(Exception ignored){}h.post(()->toast("تم الحفظ ✓"));}else{final HttpResult result=r;h.post(()->toast(error(result)));}}catch(Exception e){h.post(()->toast("فشل الحفظ"));}});}
 private void contactsScreen(){base("جهات الاتصال");Button back=btn("رجوع");content.addView(back,lp(-1,76,8));back.setOnClickListener(v->{click();home();});LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);io.execute(()->{try{HttpResult r=request("GET","/api/contacts",null,auth());if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("contacts");h.post(()->renderContacts(list,a==null?new JSONArray():a));}else{h.post(()->toast("تعذر تحميل جهات الاتصال"));}}catch(Exception e){h.post(()->toast("تعذر تحميل جهات الاتصال"));}});} private void renderContacts(LinearLayout list,JSONArray a){list.removeAllViews();if(a==null||a.length()==0){list.addView(tv("لا توجد جهات اتصال محفوظة",16,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String id=o.optString("wethaq_id"),n=o.optString("name","مستخدم");if(id.isEmpty())continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);ImageView avatar=new ImageView(this);avatar.setImageDrawable(defaultAvatar());row.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));TextView name=tv(n,18,Color.WHITE);row.addView(name,new LinearLayout.LayoutParams(0,dp(76),1));list.addView(row,lp(-1,-2,8));loadAvatarInto(id,avatar);row.setOnClickListener(v->{click();conversation(id,n);});}}
 private void conversation(String id,String n){activeId=id;activeName=n;lastRenderedMessageId=-1;CallHistory.expirePending(this,60000);base(n);Button call=btn("📹 مكالمة فيديو"),audioCall=btn("📞 مكالمة صوتية");content.addView(call,lp(-1,76,6));content.addView(audioCall,lp(-1,76,6));audioCall.setOnClickListener(v->{click();startAudioCall();});call.setOnClickListener(v->{click();startVideoCall();});messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setOverScrollMode(View.OVER_SCROLL_ALWAYS);sc.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){pullDownStartY=e.getY();pullRefreshTriggered=false;}else if(e.getAction()==MotionEvent.ACTION_MOVE&&sc.getScrollY()==0&&!pullRefreshTriggered&&e.getY()-pullDownStartY>dp(72)){pullRefreshTriggered=true;lastRenderedMessageId=-1;loadMessages();toast("جاري تحديث المحادثة…");}return false;});sc.addView(messages);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);Button mic=btn("🎙"),gallery=btn("▧"),send=btn("إرسال");input=field("اكتب رسالة…");bar.addView(mic,new LinearLayout.LayoutParams(dp(64),dp(76)));bar.addView(gallery,new LinearLayout.LayoutParams(dp(64),dp(76)));bar.addView(input,new LinearLayout.LayoutParams(0,dp(76),1));bar.addView(send,new LinearLayout.LayoutParams(dp(88),dp(76)));root.addView(bar);Button back=btn("‹ جهات الاتصال");root.addView(back,new LinearLayout.LayoutParams(-1,dp(76)));back.setOnClickListener(v->{click();contactsScreen();});send.setOnClickListener(v->{click();send();});mic.setOnClickListener(v->{click();if(recording)stopRecording(true);else startRecording();});gallery.setOnClickListener(v->{click();pickImage();});loadMessages();}
 private boolean messageLoadInFlight=false;
 private String messageCacheKey(String id){String owner=prefs.getString(ID,"guest");return MESSAGE_CACHE_PREFIX+owner+"_"+id;}
 private JSONArray readCachedMessages(String id){try{return new JSONArray(prefs.getString(messageCacheKey(id),"[]"));}catch(Exception e){return new JSONArray();}}
 private void writeCachedMessages(String id,JSONArray source){if(id==null||id.isEmpty()||source==null)return;try{JSONArray safe=new JSONArray();int from=Math.max(0,source.length()-250);for(int i=from;i<source.length();i++){JSONObject m=source.optJSONObject(i);if(m==null)continue;JSONObject copy=new JSONObject(m.toString());copy.remove("audio_data");safe.put(copy);}prefs.edit().putString(messageCacheKey(id),safe.toString()).apply();}catch(Exception ignored){}}
 private void appendCachedMessage(String id,JSONObject message){if(id==null||id.isEmpty()||message==null)return;JSONArray current=readCachedMessages(id);try{long idv=message.optLong("id",0);if(idv>0){for(int i=0;i<current.length();i++)if(current.optJSONObject(i)!=null&&current.optJSONObject(i).optLong("id",0)==idv)return;}current.put(message);writeCachedMessages(id,current);}catch(Exception ignored){}}
 private void cacheSuccessfulMessage(HttpResult r){try{if(r.code<200||r.code>=300)return;JSONObject root=new JSONObject(r.body);JSONObject m=root.optJSONObject("message");if(m!=null)appendCachedMessage(activeId,m);}catch(Exception ignored){}}
 private JSONArray mergeMessages(JSONArray local,JSONArray remote){LinkedHashMap<Long,JSONObject> map=new LinkedHashMap<>();for(JSONArray a:new JSONArray[]{local,remote}){if(a==null)continue;for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;long id=m.optLong("id",0);if(id>0)map.put(id,m);}}ArrayList<JSONObject> list=new ArrayList<>(map.values());Collections.sort(list,(a,b)->Long.compare(a.optLong("id",0),b.optLong("id",0)));int from=Math.max(0,list.size()-500);JSONArray out=new JSONArray();for(int i=from;i<list.size();i++)out.put(list.get(i));return out;}
 private void loadMessageMedia(String messageId,ImageView target){network.execute(()->{try{HttpResult r=request("GET","/api/messages/media/"+URLEncoder.encode(messageId,"UTF-8"),null,auth());if(r.code!=200)return;JSONObject z=new JSONObject(r.body);String data=z.optString("data","");if(data.isEmpty())return;byte[] raw=Base64.getDecoder().decode(data);Bitmap bm=BitmapFactory.decodeByteArray(raw,0,raw.length);if(bm==null)return;messageImageCache.put(messageId,bm);h.post(()->{if(target!=null)target.setImageBitmap(bm);});}catch(Exception ignored){}});}
 private void loadAndPlayAudio(String messageId,TextView button){network.execute(()->{try{HttpResult r=request("GET","/api/messages/media/"+URLEncoder.encode(messageId,"UTF-8"),null,auth());if(r.code!=200)return;String data=new JSONObject(r.body).optString("data","");if(!data.isEmpty())h.post(()->toggleAudio(messageId,data,button));}catch(Exception ignored){}});}
